#!/usr/bin/env bash\nset -euo pipefail\n: "${OUTBOX_DB_PASSWORD:?OUTBOX_DB_PASSWORD must be set when initializing PostgreSQL}"\npsql --username "${POSTGRES_USER:-postgres}" --dbname "${POSTGRES_DB:-construction}" \\n  --set=worker_password="$OUTBOX_DB_PASSWORD" <<'SQL'\nALTER ROLE outbox_worker WITH LOGIN PASSWORD :'worker_password'\n    NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;\nSQL